#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""SYNTIZ's TABLE model: the 32 single-cycle tables, written as tables.h (generated: do not edit it by hand).

    python3 tools/make_tables.py > tables.h

The author's own set, computed from the formulas below: nothing here is taken from any instrument. Four families of eight, each in rising
richness: geometric, additive, digital, resonant. 512 points of 12 signed bits each, DC removed and peak
normalized; nothing is smoothed or band-limited: the grain is the character."""
import math

N, BITS = 512, 12

def phase(): return [i / N for i in range(N)]
def harmonics(spec): return [sum(a * math.sin(2 * math.pi * (k * t + ph)) for k, a, ph in spec) for t in phase()]
def saw(t): return 2.0 * t - 1.0
def square(t): return 1.0 if t < 0.5 else -1.0
def tri(t): return 4.0 * abs(t - 0.5) - 1.0
def pulse(t, duty): return 1.0 if t < duty else -1.0
def shape(f): return [f(t) for t in phase()]

def fold(xs, gain):
    out = []
    for x in xs:
        v = x * gain
        for _ in range(8):
            if v > 1.0: v = 2.0 - v
            elif v < -1.0: v = -2.0 - v
            else: break
        out.append(v)
    return out

def staircase(xs, steps): return [math.floor((x * 0.5 + 0.5) * steps) / (steps - 1) * 2.0 - 1.0 for x in xs]

def pseudo_random(seed):
    out, s = [], seed & 0xFFFFFFFF
    for _ in range(N):
        s = (1103515245 * s + 12345) & 0x7FFFFFFF
        out.append(s / 0x3FFFFFFF - 1.0)
    return out

def smooth(xs, width): return [sum(xs[(i + j) % N] for j in range(width)) / width for i in range(N)]

def formant(f1, f2, a2, decay):
    return [math.exp(-decay * t) * (math.sin(2 * math.pi * f1 * t) + a2 * math.sin(2 * math.pi * f2 * t)) for t in phase()]

def build():
    sine = lambda t: math.sin(2 * math.pi * t)
    return [
        ('SINE', shape(sine)), ('TRI', shape(tri)), ('SAW', shape(saw)), ('SQR', shape(square)),
        ('PUL4', shape(lambda t: pulse(t, 0.25))), ('PUL8', shape(lambda t: pulse(t, 0.125))),
        ('DSAW', shape(lambda t: 0.5 * (saw((2 * t) % 1.0) + saw(t)))),
        ('HSIN', shape(lambda t: 2.0 * abs(math.sin(math.pi * t)) - 1.0)),
        ('ODD3', harmonics([(1, 1.0, 0), (3, 0.5, 0), (5, 0.25, 0)])),
        ('EVN3', harmonics([(1, 1.0, 0), (2, 0.5, 0), (4, 0.25, 0)])),
        ('H1N', harmonics([(k, 1.0 / k, 0) for k in range(1, 17)])),
        ('H1N2', harmonics([(k, 1.0 / (k * k), 0) for k in range(1, 25)])),
        ('ORGN', harmonics([(1, 1.0, 0), (2, 0.7, 0), (4, 0.5, 0), (8, 0.35, 0), (16, 0.2, 0)])),
        ('BELL', harmonics([(1, 1.0, 0), (3, .6, .25), (7, .45, .5), (11, .3, .75), (17, .2, 0)])),
        ('COMB', harmonics([(k, 1.0, 0) for k in range(1, 12, 2)])),
        ('DENS', harmonics([(k, 1.0 / math.sqrt(k), (k * k % 7) / 7.0) for k in range(1, 33)])),
        ('ST4', staircase(shape(sine), 4)), ('ST8', staircase(shape(tri), 8)), ('ST16', staircase(shape(saw), 16)),
        ('FLD2', fold(shape(sine), 2.0)), ('FLD4', fold(shape(sine), 4.0)),
        ('XOR', [(((i * 3) ^ (i * 5 // 2)) % 256) / 127.5 - 1.0 for i in range(N)]),
        ('SYNC', shape(lambda t: saw((t * 2.7) % 1.0))), ('NOIS', smooth(pseudo_random(20260920), 3)),
        ('RES1', formant(3.0, 7.0, 0.5, 3.0)), ('RES2', formant(5.0, 11.0, 0.6, 4.0)),
        ('RES3', formant(8.0, 17.0, 0.5, 6.0)), ('VOWA', formant(6.0, 11.0, 0.8, 2.0)),
        ('VOWE', formant(4.0, 19.0, 0.7, 2.5)), ('VOWI', formant(3.0, 27.0, 0.6, 2.5)),
        ('SPIK', [math.exp(-25.0 * t) for t in phase()]),
        ('TWIN', [1.0 if (i < 6 or 256 <= i < 262) else -0.2 for i in range(N)]),
    ]

def quantise(xs):
    dc = sum(xs) / len(xs); xs = [x - dc for x in xs]
    peak = max(abs(x) for x in xs); xs = [x / peak for x in xs] if peak else xs
    hi = (1 << (BITS - 1)) - 1
    return [max(-hi - 1, min(hi, int(round(x * hi)))) for x in xs]

if __name__ == '__main__':
    tables = build()
    assert len(tables) == 32
    print('/* SPDX-License-Identifier: MIT')
    print(' * GENERATED by tools/make_tables.py: do not edit by hand. 32 tables of 512 points, 12 signed bits. */')
    print('#ifndef WAVE_TABLES_H\n#define WAVE_TABLES_H\n#include <stdint.h>\n#define WAVE_TABLES 32\n#define WAVE_TABLE_LEN 512')
    print('static const char *const wave_table_names[WAVE_TABLES] = { %s };' % ', '.join('"%s"' % n for n, _ in tables))
    print('static const int16_t wave_tables[WAVE_TABLES][WAVE_TABLE_LEN] = {')
    for name, data in tables:
        q = quantise(data)
        print('    { /* %s */' % name)
        for i in range(0, N, 16): print('        ' + ', '.join('%d' % v for v in q[i:i + 16]) + ',')
        print('    },')
    print('};\n#endif')
